from h import *
R(9422469,"كوكيز زبدة الفول السوداني بدقيق اللوز [خالٍ من الغلوتين]",
"بحواف مقرمشة ووسط طري، كوكيز زبدة الفول السوداني بدقيق اللوز هذا يفيض بالنكهة اللذيذة. 6 مكونات فقط و20 دقيقة!",
"16 قطعة كوكيز","حصة واحدة",
["½ كوب زبدة فول سوداني طبيعية، ناعمة أو مقرمشة (غير مملحة)","4 ملاعق كبيرة شراب القيقب","2 ملعقة صغيرة فانيليا","150 جرامًا من دقيق اللوز، أي حوالي 1½ كوب","½ ملعقة صغيرة بيكربونات الصوديوم","¼ ملعقة صغيرة ملح البحر"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية) وبطّن صينية كوكيز بورق الزبدة.","في وعاء خلط متوسط، ضع زبدة الفول السوداني وشراب القيقب والفانيليا واخلطها جيدًا. استخدم شوكة أو ملعقة سيليكون للتأكد من أن المكونات ممتزجة جيدًا.","في وعاء صغير منفصل، اخفق دقيق اللوز وبيكربونات الصوديوم والملح معًا. ثم أضف المكونات الجافة إلى وعاء المكونات السائلة. اخلط جيدًا. سيكون العجين لزجًا وسميكًا، لكن واصل الخلط حتى يمتزج.","قسّم الخليط إلى 16 كرة عجين وضعها على الصينية. ثم باستخدام شوكة مبللة قليلًا، اضغط على كل كرة لتكوين نقش متقاطع على سطح كل قطعة كوكيز.","اخبز لمدة 10 دقائق، ثم أخرجه من الفرن واتركه ليبرد لمدة 10 دقائق ولا تلمس الكوكيز خلال هذه الفترة. وبعد فترة الراحة التي مدتها 10 دقائق، انقل الكوكيز إلى رف التبريد لمدة 5-10 دقائق أخرى. فترة التبريد هذه ضرورية ليتماسك الكوكيز تمامًا وتصبح الحواف مقرمشة بشكل رائع."],
["استخدم قياس الوزن للدقيق كلما أمكن. فهذا يضمن أدق النتائج. وإذا اضطررت إلى استخدام الحجم، فتأكد من وضع دقيق اللوز بالملعقة وتسوية سطحه. لا تغترفه بكوب القياس وإلا فقد تستخدم كمية زائدة من الدقيق. إذا واجهت صعوبة في خلط العجين بالملعقة أو الملعقة المسطحة، فاستعن بيديك لخلط المكونات. سيكون العجين لزجًا وسميكًا قليلًا. قسّم العجين كما أوضحت في الصورة 7 أعلاه إذا كنت تهتم بأن تكون قطع الكوكيز متقاربة الحجم. هذا الكوكيز لا ينتشر كثيرًا، لذا احرص على تشكيله بالحجم والسمك الذي تفضله قبل الخَبز. عند عمل النقش المتقاطع، بلّل الشوكة بالماء قبل الضغط على العجين. فهذا يساعد على منع التصاق الشوكة به. اغمس الشوكة في بعض الماء بعد كل بضع قطع كوكيز. لا تُفرط في خبز الكوكيز. نعم، سيبدو طريًا وقد يبدو حتى غير ناضج تمامًا، لكن هذا هو المطلوب بالضبط. احرص على ترك الكوكيز ليبرد! لا تلمسه وهو في الفرن ولا تلمسه لمدة 10 دقائق على الأقل بعد إخراجه من الفرن. وبعد انتهاء الـ 10 دقائق، انقله بحذر شديد إلى رف سلكي ليواصل التبريد. هذا الوقت الإضافي ضروري لمنح الكوكيز حوافًا مقرمشة. اتركه على الأقل 5 دقائق على رف التبريد، لكن 10 أفضل."])
R(9425725,"هاش براون بقلاية الهواء من الصفر [خيار خالٍ من الزيت]",
"هل أنت مستعد لأكثر هاش براون مقرمش وهش؟؟ مصنوع من الصفر باستخدام قلاية الهواء بـ 3 مكونات فقط لأفضل أقراص هاش براون على الإطلاق!",
"حصتان","حصة واحدة",
["1 رطل بطاطس صفراء، أي حوالي حبتي بطاطس متوسطتين","1½ ملعقة كبيرة زيت أفوكادو أو زيت طهي من اختيارك *انظر الملاحظات لخيار خالٍ من الزيت","½ ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق البصل، اختياري"],
["املأ وعاءً كبيرًا بالماء البارد وقشّر البطاطس. (أو افركها جيدًا إذا أردت ترك القشر.)","ثم باستخدام مبشرة، بشّر البطاطس في وعاء الماء. قلّبها بسرعة واتركها لمدة 20 دقيقة. ثم صفّها في مصفاة واشطفها جيدًا جدًا بالماء البارد.","انقل البطاطس المبشورة إلى منشفة مطبخ نظيفة أو مناديل ورقية واعصرها أو اضغط عليها لتجف. أنت تريدها جافة قدر الإمكان للحصول على أكثر هاش براون قرمشة.","الآن أعد البطاطس إلى الوعاء نفسه (امسحه حتى يجف أولًا) وأضف الزيت (إن استخدمته) والتوابل. اخلط جيدًا.","ادهن السلة أو رشّها (إن لزم الأمر) وضع البطاطس المتبّلة بداخلها. استخدم ملعقة سيليكون لفرد الشرائح المبشورة والضغط عليها لتكوين طبقة متساوية واطهِها على 370 درجة (185 درجة مئوية) لمدة 12-18 دقيقة، حتى تصبح ذهبية. لا حاجة إلى القلب! بالهناء والعافية!"],
["لا تتخطَّ النقع. فنقع البطاطس في الماء البارد يساعد على إزالة النشا مما يعطي بطاطس أكثر قرمشة. لذا احرص على النقع لمدة 20 دقيقة وعلى شطفها بعد ذلك أيضًا. جفّفها جيدًا جدًا! مرة أخرى، للحصول على أقصى قرمشة، تأكد من أن شرائح البطاطس المبشورة جافة جيدًا. استخدم منشفة مطبخ نظيفة لعصر السائل. افرد البطاطس في طبقة متساوية لتتقرمش بالتساوي. فالأماكن الأسمك قد لا تتقرمش بالقدر نفسه. أستخدم Ninja Foodi بسعة 8 كوارت ويكون الهاش براون عندي مقرمشًا عند 18-20 دقيقة. وإذا كنت تستخدم سلة قلاية هواء أصغر، فقد ينضج أسرع. ابدأ بالتفقد عند 10-15 دقيقة تقريبًا واطهِ حتى تصل إلى درجة القرمشة المطلوبة. وبالنسبة لقلايات الهواء الأصغر، قد تحتاج إلى العمل على دفعتين. للحصول على هاش براون حار، أضف ¼ ملعقة صغيرة من الفلفل الحار (كايين). وللحصول على هاش براون بنكهة مدخنة، أضف ½ ملعقة صغيرة من البابريكا المدخنة. *إذا كنت تتجنب الزيت وتستخدم قلاية هواء غير لاصقة، فإن هذه الوصفة تنجح أيضًا بدون الزيت. جرّبتها في Ninja Foodi ولم تلتصق. استخدم ملعقة سيليكون لفصل الحواف برفق وستخرج بسهولة. يُرجى ملاحظة أنها ستكون أقل قرمشة قليلًا بهذه الطريقة. هذه الوصفة نباتية بطبيعتها وخالية من الغلوتين وخالية من الصويا وخالية من المكسرات وخالية من جميع مسببات الحساسية الشائعة. ***تعديل بتاريخ 28 فبراير/2021 – خُفضت درجة الحرارة من 400 درجة (200° مئوية) إلى 370 درجة فهرنهايت (185° مئوية). فقد لاحظ بعض المستخدمين أن الطهي كان سريعًا جدًا. وهذا يختلف بحسب طراز القلاية. وإذا كنت قد حضّرتها سابقًا على 400 درجة دون مشكلة، فيمكنك الاستمرار في ذلك."])
R(9426064,"كب كيك الشوكولاتة النباتي الصحي",
"أكثر كب كيك شوكولاتة نباتي صحة على الإطلاق، لكنه لا يقل عن كونه مذهلًا!",
"12 كب كيك","حصة واحدة",
["6 ملاعق كبيرة هريس البطاطا الحلوة من حوالي حبة بطاطا حلوة متوسطة محمّصة ذات لب برتقالي","¾ كوب حليب اللوز أو حليب نباتي آخر","½ كوب شراب القيقب","150 جرامًا من دقيق اللوز المقشّر، أي حوالي 1½ كوب","130 جرامًا من دقيق الشوفان، أي حوالي 1½ كوب","⅓ كوب مسحوق الكاكاو الخام غير المحلى","2½ ملعقة صغيرة بيكنج باودر","¼ ملعقة صغيرة ملح البحر","1 كوب فاصولياء سوداء مطبوخة أو معلبة","2 ملعقة كبيرة مسحوق الكاكاو الخام غير المحلى","¼ كوب شراب القيقب"],
["لتحضير البطاطا الحلوة: سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية). ثم افرك البطاطا حتى تنظف وضعها على صينية خبز وحمّصها لمدة 35-45 دقيقة تقريبًا، أو حتى تُغرز فيها الشوكة بسهولة. أو، إذا كانت لديك قلاية هواء، يمكنك قليها بالهواء الساخن بهذه الطريقة لتوفير الوقت. ضعها جانبًا.","سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وبطّن قالب المافن بأكواب ورق الزبدة.","قشّر البطاطا الحلوة أو اغرف لبها واهرسه على طبق. ثم قس ست ملاعق كبيرة (وليس أكثر) لاستخدامها في العجين وضعها في وعاء كبير. أضف الحليب وشراب القيقب إلى الوعاء نفسه واخفق حتى يمتزج.","بعد ذلك، أضف جميع المكونات الجافة إلى الوعاء نفسه وقلّب حتى تمتزج.","وزّع العجين على قوالب المافن الاثني عشر واخبزه لمدة 20-22 دقيقة، أو حتى يخرج عود الأسنان المغروز في الوسط نظيفًا. ضعه جانبًا ليبرد تمامًا قبل وضع الكريمة عليه.","ضع جميع مكونات الكريمة في خلاط عالي السرعة أو محضّر طعام واخلطها حتى تصبح ناعمة. وبعد أن يبرد الكب كيك، استخدم كيس تزيين لوضع الكريمة عليه واستمتع به."],
["زِن الدقيق للحصول على أدق النتائج. أنصح بشدة بعدم الاعتماد على الأكواب في القياس عند الخَبز. إذا لم يكن لديك ميزان مطبخ، فيمكنك وضع الدقيق بالملعقة في كوب القياس واستخدام سكين لكشط الزائد، وستحصل على نتائج مماثلة. لا تغترف الدقيق من الكيس! استخدم بيكنج باودر طازجًا وفعّالًا. فالبيكنج باودر المفتوح في الخزانة لأكثر من 6 أشهر قد يبدأ بفقدان فعاليته. إذا أمكن، حمّص البطاطا الحلوة قبل يوم واحد، أو قبل عدة ساعات من موعد خَبز الكب كيك. اترك الكب كيك يبرد في قالب المافن لمدة 10 دقائق على الأقل قبل لمسه. ثم انقله إلى رف التبريد ليبرد تمامًا قبل وضع الكريمة عليه. طعمه أفضل في اليوم الأول والثاني، لكن يمكنك حفظ المتبقي في الثلاجة لمدة تصل إلى 4 أيام. احفظه في وعاء محكم الإغلاق للحفاظ على الرطوبة. أو جمّد الكب كيك بدون كريمة في وعاء محكم الإغلاق مناسب للتجميد لمدة تصل إلى 3 أشهر. أنصح بتحضير الكريمة طازجة قبل التقديم."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","For the Frosting":"للكريمة","For the frosting":"للكريمة","Before you begin":"قبل أن تبدأ","For the cupcakes":"للكب كيك"})
R(9426702,"بيتزا الجاك فروت بصلصة الباربكيو مع خيار Instant Pot",
"الجاك فروت المفتت وجبن الموزاريلا النباتي يشكلان مزيجًا مذهلًا على بيتزا الجاك فروت هذه! إنها بنكهة مدخنة ومفتتة كلحم الخنزير المسحوب، مع صلصة باربكيو منزلية رائعة، لكنها نباتية 100%!",
"4 حصص","حصة واحدة",
["علبة جاك فروت أخضر صغير 20 أونصة في محلول ملحي أو ماء وليس في شراب","½ كوب كاتشب","¼ كوب خل التفاح","¼ كوب ماء","2 ملعقة كبيرة تاماري أو صلصة الصويا إن لم تكن تتجنب الغلوتين","1 ملعقة كبيرة شراب القيقب","1 ملعقة كبيرة خردل أصفر","1 ملعقة صغيرة بابريكا مدخنة","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة مسحوق البصل","2 رغيف خبز مسطح من الحبوب المتعددة بقطر 12 بوصة أو خبز مسطح/عجينة من اختيارك بحجم مماثل","½ وصفة من جبن الموزاريلا النباتي","¼ كوب بصل أحمر مقطع شرائح رفيعة"],
["ابدأ بتحضير جبن الموزاريلا النباتي. ثم ضعه في الثلاجة بينما تجهز بقية المكونات، ليتماسك قليلًا مما يسهّل اغترافه ووضعه على العجينة.","صفِّ الجاك فروت واشطفه جيدًا جدًا لإزالة نكهة المحلول الملحي. ثم انقله إلى محضّر الطعام وقلّب بالنبض حتى يتفتت. لا تُفرط في الفرم، فأنت تريد قطعًا خشنة وليس لحمًا مفرومًا. أو يمكنك نقل الجاك فروت إلى لوح تقطيع وتفتيت القطع بأصابعك أو بشوكتين. ضعه جانبًا.","اخفق جميع مكونات الصلصة معًا في وعاء صغير وضعها جانبًا.","ضع الجاك فروت المفتت في مقلاة واسكب الصلصة فوقه. قلّب على نار متوسطة مع الخلط من حين لآخر حتى تُمتص الصلصة في معظمها. سيستغرق ذلك حوالي 8-10 دقائق.","ضع الجاك فروت المفتت وجميع مكونات الصلصة في Instant Pot. (لا حاجة إلى خفق الصلصة مسبقًا في وعاء منفصل.) اخلط جيدًا وأغلق الغطاء وضع الصمام في وضع الإغلاق. اطهِ على ضغط عالٍ لمدة 3 دقائق واترك Instant Pot يُطلق الضغط طبيعيًا، وسيستغرق ذلك حوالي 10 دقائق. وإذا لم يتحرر الضغط بالكامل بعد 10 دقائق، فأطلق الضغط المتبقي بسرعة.","سخّن الفرن مسبقًا على 425 درجة فهرنهايت (220 درجة مئوية) وبطّن صينية خبز كبيرة تتسع للرغيفين المسطحين بورق الزبدة، أو استخدم صينيتين أصغر.","وزّع الجاك فروت على الرغيفين المسطحين، واغرف جبن الموزاريلا النباتي باستخدام مغرفة كرات البطيخ أو ملعقة صغيرة. ضع الجبن على شكل دفعات على البيتزا كلها وانثر البصل الأحمر فوقها. اخبزها لمدة 13-18 دقيقة، أو حتى تصبح الحواف ذهبية ويذوب الموزاريلا قليلًا."],
["احرص على شطف الجاك فروت جيدًا جدًا لإزالة أكبر قدر ممكن من نكهة المحلول الملحي. لا تُفرط في فرم الجاك فروت إذا كنت تستخدم محضّر الطعام. فقط قلّب بالنبض حتى يتفتت، دون فرمه ناعمًا. فأنت تريد قطعًا أخشن. وإذا بقيت أي قطع كاملة لم تتفتت، فمزّقها بيديك لتجنب الإفراط في فرم بقية القطع. تبقى بيتزا الجاك فروت صالحة في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق. ويمكنك إعادة تسخينها في الفرن أو في فرن التحميص الصغير."],
{"For the Jackfruit":"للجاك فروت","For the Pizza":"للبيتزا","To Cook the Jackfruit on Stove Top":"لطهي الجاك فروت على الموقد","To Cook the Jackfruit in your Instant Pot":"لطهي الجاك فروت في Instant Pot","For the Pizza Assembly":"لتجميع البيتزا"})
R(9429573,"مافن الموز والسبانخ",
"بوعاء واحد فقط يمكنك تحضير مافن الموز والسبانخ الهش واللذيذ. كمية كبيرة من الفاكهة والخضار المخفية لوجبة فطور أو حلوى صحية.",
"36 قطعة مافن صغير","حصة واحدة",
["1 كوب دقيق الأرز البني أو أرز بني* (انظر الملاحظات)","1 كوب دقيق الشوفان أو شوفان مجروش**، خالٍ من الغلوتين إن أردت","2 ملعقة صغيرة بيكنج باودر","1 ملعقة صغيرة بيكربونات الصوديوم","¼ ملعقة صغيرة ملح البحر","½ كوب + 2 ملعقة كبيرة موز مهروس شديد النضج، أي حوالي موزتين متوسطتين","¼ كوب شراب القيقب","¼ كوب صلصة التفاح غير المحلاة","1 ملعقة كبيرة مكدّسة قشر ليمون مبشور، أي حوالي ليمونة متوسطة","1 كوب حليب الصويا غير المحلى أو حليب اللوز أو الكاجو","2 كوب سبانخ صغيرة (بيبي) (2 كوب قبل التقطيع) مفرومة ناعمًا في محضّر الطعام أو الخلاط، دون أن تتحول إلى هريس"],
["سخّن الفرن مسبقًا على 375 درجة فهرنهايت (190 درجة مئوية).","اهرس الموز في وعاء خلط كبير ثم أضف جميع المكونات السائلة المتبقية واخلط جيدًا. ثم أضف المكونات الجافة إلى الوعاء نفسه وقلّب حتى تمتزج دون إفراط في الخلط.","املأ صواني المافن الصغير تقريبًا حتى الحافة، مع ترك مساحة صغيرة فقط للانتفاخ. ستحصل على 36 قطعة مافن صغير.","اخبز لمدة 13-16 دقيقة، أو حتى يخرج عود الأسنان المغروز في وسط المافن نظيفًا. أخرجه من الفرن واتركه ليبرد لمدة 10 دقائق قبل إخراجه من صينية المافن واستمتع به."],
["** إذا لم يكن لديك دقيق الأرز البني أو دقيق الشوفان، فضع كوبًا من الأرز وكوبًا من الشوفان في خلاط عالي السرعة واخلطهما حتى تصل إلى قوام الدقيق. قد يستغرق ذلك من 30-60 ثانية بحسب جهازك. استخدم موزًا شديد النضج. فكلما زادت البقع البنية كان ذلك أفضل للحصول على أكبر قدر ممكن من الحلاوة الطبيعية. يُفضَّل السبانخ الصغيرة الطازجة على المجمدة. أجد أن السبانخ الطازجة نكهتها أخف من المجمدة وطعمها أفضل عند استخدامها في حلوى. لا تهرس السبانخ وإلا سيتحول المافن كله إلى اللون الأخضر. وقد يكون ذلك منفرًا للأطفال الصغار، لذا أفضّل أن أبقيها مفرومة ناعمًا لتحافظ المافن على لونها المائل إلى الأصفر. وإذا لم يكن لديك سبانخ، فيمكنك استخدام الكرنب الورقي (كيل) أيضًا. فقط تذكّر أن نكهة الكيل أقوى، لذا قد ترغب في تقليل الكمية قليلًا. ولأن هذا المافن الصحي لا يحتوي تقريبًا على أي دهون، فتجنب أكواب ورق الزبدة، أو احرص على رشّها برذاذ مانع للالتصاق لمنع التصاق المافن بالورق. استخدم صينية مافن غير لاصقة، أو احرص على دهن القوالب حتى لا يلتصق المافن ويتفتت. اترك مافن الموز والسبانخ يبرد 5-10 دقائق بعد إخراجه من الفرن قبل إخراجه من صينية المافن. أستخدم صينية مافن غير لاصقة ولا أحتاج إلى دهنها، ويخرج هذا المافن بسهولة دون أن يتكسر إطلاقًا بعد فترة التبريد. ولأن هذا المافن قليل جدًا في السكر، يمكنك إضافة ¼-⅓ كوب من رقائق الشوكولاتة (خالية من الألبان إذا كانت نباتية) إذا كان لديك من تريد إرضاءهم من الصعبي الإرضاء. فتفضيل الحلاوة يعتمد على ما اعتدت عليه، وهذا المافن يناسبنا بدون رقائق الشوكولاتة، لكنك تعرف عائلتك أفضل."],
{"Dry Ingredients":"المكونات الجافة","Wet Ingredients":"المكونات السائلة"})
R(9430487,"لحم بقري نباتي مع البروكلي",
"لحم بقري نباتي مشبع مع البروكلي مصنوع باستخدام مجعدات الصويا لطبق أفضل من الطعام الجاهز!",
"4 حصص","حصة واحدة",
["4 أونصات مجعدات الصويا (Soy Curls)، أي حوالي نصف كيس من علامة Butler's","2 كوب مرق خضار","4 أكواب زهيرات بروكلي","¼ كوب صلصة صويا قليلة الصوديوم أو تاماري لخلو الوصفة من الغلوتين","½ كوب ماء","2 ملعقة كبيرة شراب القيقب","3 فصوص ثوم مقشّرة + مفرومة","2 ملعقة صغيرة زنجبيل طازج مبشور","1 ملعقة كبيرة دقيق التابيوكا أو نشا الذرة","½ ملعقة صغيرة فلاكس الفلفل الأحمر، اختياري","نودلز الفيرميشيلي أو أرز بني","بصل أخضر","سمسم"],
["ضع مجعدات الصويا في وعاء كبير وغطِّها بالمرق. اتركها تنقع لمدة 7-8 دقائق تقريبًا، مع التقليب عند منتصف المدة لضمان نقعها كلها.","في هذه الأثناء، اطهِ البروكلي على البخار في قدر أو مقلاة بها ماء لمدة 4-5 دقائق، حتى يلين عند غرزه بالشوكة لكنه يبقى مقرمشًا قليلًا (أو حتى درجة النضج التي تريدها). ثم صفّه وضعه جانبًا.","سخّن مقلاة حديد زهر أو مقلاة كبيرة أخرى على نار متوسطة إلى عالية ثم أخرج المجعدات من المرق (مع الاحتفاظ بالمرق) وقلّبها جافة لمدة 3-4 دقائق مع التحريك المستمر لتحميرها قليلًا.","في هذه الأثناء، ضع جميع مكونات الصلصة في الوعاء الذي فيه بقية المرق واخفقها حتى تمتزج. ثم أضف الصلصة والبروكلي إلى مقلاة المجعدات ودعها تغلي على نار هادئة لمدة 2-3 دقائق لتتكاثف الصلصة قليلًا. قدّمها مع الأرز أو النودلز أو البصل الأخضر و/أو السمسم."],
["قلّب المجعدات كثيرًا أثناء التقليب في المقلاة لمنع الالتصاق لأننا لا نستخدم الزيت في هذه الوصفة. وإذا كنت لا تتجنب الزيت، فيمكنك استخدام ملعقة كبيرة من زيت السمسم لإضافة نكهة.","يبقى المتبقي صالحًا في الثلاجة لمدة 2-3 أيام في وعاء محكم الإغلاق."],
{"For the sauce":"للصلصة","For serving":"للتقديم"})
R(9433642,"دونات القرع النباتي [خالٍ من الغلوتين وخالٍ من الزيت أيضًا]",
"دونات القرع النباتي هذا يفيض بنكهة القرع، ومتبّل بالقرفة وطري ولذيذ بإتقان.",
"12 دونات","حصة واحدة",
["1 كوب هريس القرع","½ كوب صلصة التفاح غير المحلاة","¼ كوب شراب القيقب","180 جرامًا من دقيق الشوفان الخالي من الغلوتين (حوالي 1½ كوب)","75 جرامًا من سكر جوز الهند غير المكرر أو سكر بني (حوالي ⅓ كوب)","2 ملعقة صغيرة قرفة","1½ ملعقة صغيرة بيكنج باودر","½ كوب تمر منزوع النوى مكبوس برفق","¾ كوب ماء عذب","1½ ملعقة صغيرة قرفة"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية).","ضع المكونات السائلة في وعاء كبير واخلطها جيدًا. ثم أضف المكونات الجافة إلى الوعاء نفسه واخلط حتى تمتزج.","وزّع الخليط على صواني الدونات غير اللاصقة بما يكفي لتحضير 12 دونات. اخبزها لمدة 18-20 دقيقة، أو حتى تصبح متماسكة عند اللمس لكنها تلين قليلًا عند الضغط عليها برفق بإصبعك. ثم أخرجها من الفرن واتركها لتبرد 10 دقائق على الأقل قبل نقلها إلى رف التبريد.","بينما تبرد الدونات، حضّر الطلاء. ضع التمر والماء والقرفة في الخلاط واخلطها حتى تصبح ناعمة تمامًا. ثم انقلها إلى طبق ضحل.","عندما تبرد الدونات، اغمسها في الطلاء وضعها على رف التبريد بحيث يكون جانب الطلاء لأعلى. اتركها لتجف واستمتع بها."],
["زِن الدقيق إن أمكن للحصول على أفضل النتائج. استخدم صينية دونات سيليكون غير لاصقة لتجنب دهن الصينية إذا كنت تتجنب الزيت. خرجت الدونات عندي بسهولة بعد أن بردت. اترك الدونات لتبرد 10-15 دقيقة قبل محاولة إخراجها من الصينية. فإذا كانت الدونات ساخنة، فقد تنكسر. اترك دونات القرع تبرد على رف التبريد لمدة 10 دقائق قبل تغطيتها بالطلاء. وإذا لم يكن لديك خلاط قوي أو كان التمر جافًا جدًا، فانقعه في ماء بارد لمدة 15-20 دقيقة قبل الخلط. فهذا سيلينه ويساعده على التفتت بشكل أنعم. تبقى الدونات المتبقية رطبة وطازجة في وعاء محكم الإغلاق في درجة حرارة الغرفة لمدة 2-3 أيام، رغم أن طعمها أفضل في اليوم الذي تُحضَّر فيه. المعلومات الغذائية لا تشمل الطلاء الاختياري."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","For the Glaze (Optional)":"للطلاء (اختياري)","Optional Glaze":"طلاء اختياري"})
R(9437802,"معكرونة البروكلي والهليون",
"طبق معكرونة البروكلي والهليون هذا مشبع وغني بالنكهة ويجهز في 30 دقيقة أو أقل.",
"4 حصص","حصة واحدة",
["½ رطل (8 أونصات) معكرونة بيني، أي حوالي نصف عبوة معكرونة قياسية","1 حبة بصل أصفر مفرومة ناعمًا","5 فصوص ثوم مفرومة","1 حزمة هليون بعد قص الأطراف، ومقطع إلى قطع بطول 1 بوصة","4 أكواب زهيرات بروكلي","1 كوب مرق خضار","½ كوب حليب نباتي","1 ملعقة كبيرة دقيق التابيوكا أو نشا الذرة","¼ ملعقة صغيرة فلاكس الفلفل الأحمر، اختياري ولكنه موصى به","¼ كوب جبن بارميزان نباتي","ملح + فلفل حسب الرغبة"],
["اغلِ قدرًا كبيرًا من الماء المملح بسخاء. ثم اسلق المعكرونة حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". صفّها لكن احتفظ ببعض ماء المعكرونة، وضعها جانبًا.","في هذه الأثناء، استخدم مقلاة عميقة لتقليب البصل والثوم مع 2-3 ملاعق كبيرة من الماء على نار متوسطة حتى يصبحا شفافين، أي حوالي 3-4 دقائق. ثم أضف الهليون والبروكلي وتبّلهما بالملح والفلفل وواصل التقليب حتى يلينا، أي حوالي 6-8 دقائق.","بينما تُطهى الخضار، اخلط المرق والحليب ونشا التابيوكا وفلاكس الفلفل الأحمر في وعاء أو كوب قياس. اخلط جيدًا ثم اسكب الصلصة في المقلاة مع الخضار. دعها تغلي على نار هادئة حتى تتكاثف، أي حوالي 2-3 دقائق ثم أطفئ النار.","بحلول هذا الوقت يجب أن تكون المعكرونة قد نضجت، فأضفها إلى المقلاة مع الصلصة والخضار ومعها جبن البارميزان النباتي، وقلّب جيدًا.","اختياري: للحصول على صلصة أخف، أضف بعض ماء المعكرونة الذي احتفظت به إلى المقلاة وقلّب. (حسب تفضيلك.)"],
[])
